import React, { useEffect, useState } from 'react';
import { db } from '../firebase-config';
import { collection, query, where, getDocs, doc, updateDoc } from 'firebase/firestore';
import { auth } from '../firebase-config';
import './Profile.css'; // Import des styles pour les cartes

const Profile = () => {
  const [activities, setActivities] = useState([]);
  const [totalRemainingSadaqa, setTotalRemainingSadaqa] = useState(0);
  const [sadaqaPaid, setSadaqaPaid] = useState(''); // Montant de Sadaqa payé

  useEffect(() => {
    const fetchActivities = async () => {
      try {
        const user = auth.currentUser;
        if (user) {
          const activitiesCollectionRef = collection(db, 'activities');
          const q = query(activitiesCollectionRef, where('userId', '==', user.uid));
          const querySnapshot = await getDocs(q);

          const fetchedActivities = [];
          let sadaqaRemaining = 0;

          querySnapshot.forEach((doc) => {
            const data = doc.data();
            fetchedActivities.push({ id: doc.id, ...data });

            // Calculer le montant restant pour les Sadaqa
            if (data.sadaqaStatus === 'Pas encore' || data.sadaqaStatus === 'Partiellement payé') {
              const remaining = data.sadaqaAmount - (data.sadaqaPaid || 0);
              sadaqaRemaining += remaining;
            }
          });

          setActivities(fetchedActivities);
          setTotalRemainingSadaqa(sadaqaRemaining);
        }
      } catch (error) {
        console.error('Erreur lors du chargement des activités :', error);
      }
    };

    fetchActivities();
  }, []);

  // Fonction pour mettre à jour la Sadaqa dans la base de données
  const handleUpdateSadaqa = async () => {
    try {
      let remainingToPay = parseFloat(sadaqaPaid); // Montant à payer
      const updatedActivities = [...activities]; // Copie des activités

      for (let i = 0; i < updatedActivities.length; i++) {
        const activity = updatedActivities[i];
        const remainingSadaqa = activity.sadaqaAmount - (activity.sadaqaPaid || 0);

        if (remainingToPay <= 0) break; // Si tout est payé, arrêter

        if (remainingSadaqa > 0) {
          const amountToPay = Math.min(remainingToPay, remainingSadaqa); // Montant à payer pour ce jour
          activity.sadaqaPaid = (activity.sadaqaPaid || 0) + amountToPay; // Mettre à jour le montant payé
          remainingToPay -= amountToPay; // Réduire le montant restant à payer

          // Mettre à jour dans Firestore
          const activityDocRef = doc(db, 'activities', activity.id);
          await updateDoc(activityDocRef, {
            sadaqaPaid: activity.sadaqaPaid,
          });
        }
      }

      alert('Sadaqa mise à jour avec succès !');
      setSadaqaPaid(''); // Réinitialiser le champ
      window.location.reload(); // Rafraîchir la page pour afficher les nouvelles données
    } catch (error) {
      console.error('Erreur lors de la mise à jour de la Sadaqa :', error);
    }
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center mb-4">👤 Profil</h1>

      {/* Afficher les activités par jour */}
      <div className="activities-container">
        {activities.map((activity) => (
          <div key={activity.id} className="activity-card">
            <h5 className="activity-date">
              📅 {new Date(activity.date).toLocaleDateString('fr-FR', {
                weekday: 'long',
                day: 'numeric',
                month: 'numeric',
                year: 'numeric',
              })}
            </h5>
            <p>📈 <strong>Bénéfices :</strong> {activity.totalGains || 0} Dhs</p>
            <p>🤲 <strong>Reste de Sadaqa :</strong> {(activity.sadaqaAmount - (activity.sadaqaPaid || 0)).toFixed(2)} Dhs</p>
          </div>
        ))}
      </div>

      {/* Afficher le montant total restant pour les Sadaqa */}
      <div className="card mt-4 sadaqa-card">
        <div className="card-body text-center">
          <h3 className="card-title">🤲 Sadaqa restante</h3>
          <p className="sadaqa-amount">
            Montant total restant : <strong>{totalRemainingSadaqa.toFixed(2)} Dhs</strong>
          </p>

          {/* Afficher la barre d'ajout uniquement si le montant restant est supérieur à 0 */}
          {totalRemainingSadaqa > 0 && (
            <div className="update-sadaqa">
              <input
                type="number"
                className="form-control"
                placeholder="Montant payé"
                value={sadaqaPaid}
                onChange={(e) => setSadaqaPaid(e.target.value)}
              />
              <button
                className="btn btn-primary mt-2"
                onClick={handleUpdateSadaqa}
              >
                Ajouter Sadaqa
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;
